function Main(raw_input) {
	const [line] = raw_input.split("\n");
	const [ d, t, s ] = toNumArray(line);

	let isYes = t * s >= d;
	console.log(isYes ? 'Yes': 'No');
}

//*この行以降は編集しないでください（標準入出力から一度に読み込み、Mainを呼び出します）
